#!/usr/bin/env bash
# deps/lock-deps.sh - (Re)generate the pinned apt dependency lock for the
# current ROS_DISTRO.
#
# MAINTAINER tool. The resulting deps/<ROS_DISTRO>.lock is committed to the
# repository and shipped to everyone, so each `./setup.sh` installs the same
# dependency versions. Users never run this; they just run setup.sh.
#
# It resolves bagwiz's declared dependencies (package.xml) to apt packages
# via rosdep and pins each to the version the configured ROS apt repository
# currently offers (apt "Candidate"). Only the directly declared packages
# are pinned -- not the whole transitive closure -- so the lock never carries
# base system libraries (libc6, ...) that could be unsafely downgraded on a
# user's machine.
#
# Regenerate both locks from the canonical ROS images (run from the repo
# root), which keeps the result independent of any developer's machine:
#
#   for distro in humble jazzy; do
#     docker run --rm -e HOST_UID="$(id -u)" -e HOST_GID="$(id -g)" \
#       -v "$PWD":/ws -w /ws "ros:${distro}" bash -c '
#         apt-get update -qq && rosdep update --rosdistro "$ROS_DISTRO" \
#         && ./deps/lock-deps.sh \
#         && chown "$HOST_UID:$HOST_GID" "deps/$ROS_DISTRO.lock"'
#   done
#
# Requires: ROS_DISTRO set, rosdep available, apt lists updated.

set -euo pipefail

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
WORKSPACE_DIR="$(cd -- "${SCRIPT_DIR}/.." && pwd)"

if [[ -z ${ROS_DISTRO:-} ]]; then
    echo "[lock-deps.sh] ROS_DISTRO is not set. Source your ROS environment first." >&2
    exit 1
fi

if ! command -v rosdep >/dev/null 2>&1; then
    echo "[lock-deps.sh] 'rosdep' is not installed or not on PATH." >&2
    exit 1
fi

lock_file="${SCRIPT_DIR}/${ROS_DISTRO}.lock"

echo "[lock-deps.sh] Resolving apt package names via rosdep (distro=${ROS_DISTRO})"
# Read every dependency key declared in package.xml. rosdep's own `keys`
# and `install` commands hide deps already provided by the sourced ROS
# install, so parse the manifest directly to get the complete declared set
# regardless of the environment used to generate the lock.
mapfile -t keys < <(
    grep -oP '<(buildtool_depend|build_depend|build_export_depend|exec_depend|depend|test_depend|run_depend|doc_depend)[^>]*>\K[^<]+' \
        "${WORKSPACE_DIR}/package.xml" |
        sort -u
)

if [[ ${#keys[@]} -eq 0 ]]; then
    echo "[lock-deps.sh] No dependency keys found in package.xml -- nothing to lock." >&2
    exit 1
fi

# `rosdep resolve` prints an installer tag line ("#apt") before each batch of
# resolved package names; keep the non-tag lines and split into names.
mapfile -t names < <(
    rosdep resolve "${keys[@]}" --rosdistro "${ROS_DISTRO}" 2>/dev/null |
        grep -vE '^#' |
        tr ' ' '\n' |
        grep -vE '^$' |
        sort -u
)

if [[ ${#names[@]} -eq 0 ]]; then
    echo "[lock-deps.sh] rosdep resolved no apt packages -- nothing to lock." >&2
    exit 1
fi

echo "[lock-deps.sh] Pinning ${#names[@]} packages to their apt candidate versions"
tmp_lock="$(mktemp)"
trap 'rm -f "${tmp_lock}"' EXIT
{
    echo "# Generated by deps/lock-deps.sh for ROS ${ROS_DISTRO}. Do not edit by hand."
    echo "# Pinned apt versions for bagwiz's declared build dependencies, committed"
    echo "# to the repo and consumed by setup.sh so every install matches."
} >"${tmp_lock}"

for name in "${names[@]}"; do
    version="$(apt-cache policy "${name}" | awk '/Candidate:/{print $2; exit}')"
    if [[ -z ${version} || ${version} == "(none)" ]]; then
        echo "[lock-deps.sh] No candidate version for '${name}'. Is apt updated and" >&2
        echo "[lock-deps.sh] the ROS apt repository configured?" >&2
        exit 1
    fi
    echo "${name}=${version}" >>"${tmp_lock}"
done

mv "${tmp_lock}" "${lock_file}"
trap - EXIT
echo "[lock-deps.sh] Wrote ${#names[@]} pinned packages to deps/${ROS_DISTRO}.lock"
